mapper.update:
UPDATE lessons
SET title = #{title},
    description = #{description},
    scheduled_at = #{scheduledAt}
WHERE id = #{id}

mapper.select:
SELECT id, course_id, title, description, scheduled_at, outcome, paid
FROM lessons
WHERE id = #{lessonId}

SELECT EXISTS(
    SELECT 1
    FROM lesson_files
    WHERE lesson_id = #{lessonId} AND file_id = #{fileId}
)
